/// <summary>
/// MPJ_28395_Stock reservation - 21/07/2022
/// Contract class <c>METSalesOrderHoldClearContract</c> to maintain all parameters required
/// </summary>
[   
    DataContract
]
class METSalesOrderHoldClearContract 
{
    METSalesOrderTypeID     metSalesOrderTypeId;
    int                     tasks;
    List                    salesIdList = new List(Types::String);

}

Method.Source:
/// <summary>
/// Parameter method which holds values of Metcash sales order type
/// </summary>
/// <param name = "_metSalesOrderTypeID">MET Sales order type Id</param>
/// <returns>MET Sales order type Id</returns>
[DataMemberAttribute('MetSalesOrderType')]
public MetSalesOrderTypeId parmMetSalesOrderTypeId(METSalesOrderTypeID _metSalesOrderTypeID =  metSalesOrderTypeId)
{
    metSalesOrderTypeId = _metSalesOrderTypeId;
    return metSalesOrderTypeId;
}

[DataMemberAttribute('SalesIdList'),
 SysOperationControlVisibilityAttribute(false),
 AifCollectionTypeAttribute(identifierStr(_salesIdListList), Types::String)]
public List parmSalesIdList(List _salesIdList = salesIdList)
{
    salesIdList = _salesIdList;
    return salesIdList;
}

/// <summary>
/// Parameter method which holds value of number of sub tasks
/// </summary>
/// <param name = "_tasks">Sub tasks</param>
/// <returns>Number of sub tasks</returns>
/// 
[
    DataMemberAttribute('NumberofTasks'),
    SysOperationLabelAttribute(literalstr("Tasks")),
    SysOperationHelpText(literalstr("Specify number of tasks to run the batch job")),
    SysOperationDisplayOrderAttribute('2')
]
public int parmTasks(int _tasks = tasks)
{
    tasks = _tasks;
    return tasks;
}
